head.script:
scwin.screenId = "jldfil05002";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_82_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) === 'KRW'); } }, { id: "c_when_83_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) !== 'KRW'); } }, { id: "c_when_88_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) === 'KRW'); } }, { id: "c_when_89_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) !== 'KRW'); } }, { id: "c_when_95_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) === 'KRW'); } }, { id: "c_when_96_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) !== 'KRW'); } }, { id: "c_when_101_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) === 'KRW'); } }, { id: "c_when_102_txt", fn: function(){ return ((dma_readDataVO.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.currIsoCd"); })()) !== 'KRW'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_invstgClmTpCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("invstgClmTpCd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.onload();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05002.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05002' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.maxLenCheckVars = undefined; try { scwin.maxLenCheckVars = /* sdd-asis-lifecycle:begin maxLenCheckVars — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05002' }); }

scwin.maxLenCheckNames = undefined; try { scwin.maxLenCheckNames = /* sdd-asis-lifecycle:begin maxLenCheckNames — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05002' }); }

scwin.maxLenCheckMax = undefined; try { scwin.maxLenCheckMax = /* sdd-asis-lifecycle:begin maxLenCheckMax — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05002' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05002.onpageload' });
    }
};


